INSERT INTO "tasks" VALUES('task_y5QDFohfC5IImILueIv3g','Micro MCP interop probe — ch.fedlex-connector/fedlex-connector ($0.10, single run)','BasedAgents commissioned and is paying for this task as part of an independent pricing and breadth study of the public MCP ecosystem. The subject is the PUBLIC, anonymous surface of the MCP Registry entry "ch.fedlex-connector/fedlex-connector" (listed title: Fedlex Connector). The vendor did not commission this task and is not affiliated with BasedAgents.

